package main

// End-to-end test: build the real binary, disassemble testdata/sample.xlsm and compare the whole output
// directory with testdata/golden/sample/. The fixture is generated by testdata/gen (see its doc).
//
// When the output changes on purpose, refresh the golden files and review the diff:
//
//	go test -run TestE2E -update .

import (
	"bytes"
	"errors"
	"flag"
	"io/fs"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
	"testing"
)

var update = flag.Bool("update", false, "rewrite testdata/golden from the current output")

const (
	fixture   = "testdata/sample.xlsm"
	goldenDir = "testdata/golden/sample"
)

var binPath string

func TestMain(m *testing.M) {
	flag.Parse()
	dir, err := os.MkdirTemp("", "disassemble_excel-e2e-")
	if err != nil {
		panic(err)
	}
	binPath = filepath.Join(dir, "disassemble_excel")
	if out, err := exec.Command("go", "build", "-o", binPath, ".").CombinedOutput(); err != nil {
		_ = os.RemoveAll(dir)
		panic("go build: " + err.Error() + "\n" + string(out))
	}
	code := m.Run()
	_ = os.RemoveAll(dir)
	os.Exit(code)
}

type result struct {
	stdout, stderr string
	code           int
}

func runBin(t *testing.T, args ...string) result {
	t.Helper()
	cmd := exec.Command(binPath, args...)
	var stdout, stderr bytes.Buffer
	cmd.Stdout, cmd.Stderr = &stdout, &stderr
	err := cmd.Run()
	code := 0
	var exitErr *exec.ExitError
	if errors.As(err, &exitErr) {
		code = exitErr.ExitCode()
	} else if err != nil {
		t.Fatalf("run %v: %v", args, err)
	}
	return result{stdout.String(), stderr.String(), code}
}

// Values that differ on every run or on every machine. Everything else in the output must be byte-identical.
var unstable = []struct {
	re   *regexp.Regexp
	repl string
}{
	{regexp.MustCompile(`"extracted_at": "[^"]*"`), `"extracted_at": "<EXTRACTED_AT>"`},
	{regexp.MustCompile("(元 Excel ファイル（絶対パス） \\| )`[^`]*`"), "$1`<ABS_PATH>`"},
	{regexp.MustCompile(`(抽出日時 \| )[^|]*\|`), "$1<EXTRACTED_AT> |"},
}

func normalize(b []byte) []byte {
	for _, u := range unstable {
		b = u.re.ReplaceAll(b, []byte(u.repl))
	}
	return b
}

// readTree returns every regular file under root, keyed by slash-separated relative path.
func readTree(t *testing.T, root string) map[string][]byte {
	t.Helper()
	files := map[string][]byte{}
	err := filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
		if err != nil || d.IsDir() {
			return err
		}
		b, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		rel, err := filepath.Rel(root, path)
		if err != nil {
			return err
		}
		files[filepath.ToSlash(rel)] = normalize(b)
		return nil
	})
	if err != nil {
		t.Fatalf("read %s: %v", root, err)
	}
	return files
}

func sortedKeys(m map[string][]byte) []string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}

func TestE2E(t *testing.T) {
	out := filepath.Join(t.TempDir(), "out")
	r := runBin(t, fixture, "-o", out)
	if r.code != 0 {
		t.Fatalf("exit %d, stderr:\n%s", r.code, r.stderr)
	}
	if r.stdout != "" {
		t.Errorf("stdout must stay empty (progress goes to stderr), got:\n%s", r.stdout)
	}
	got := readTree(t, out)

	if *update {
		if err := os.RemoveAll(goldenDir); err != nil {
			t.Fatal(err)
		}
		for _, rel := range sortedKeys(got) {
			p := filepath.Join(goldenDir, filepath.FromSlash(rel))
			if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil {
				t.Fatal(err)
			}
			if err := os.WriteFile(p, got[rel], 0o644); err != nil {
				t.Fatal(err)
			}
		}
		t.Logf("rewrote %d golden files under %s", len(got), goldenDir)
		return
	}

	want := readTree(t, goldenDir)
	if len(want) == 0 {
		t.Fatalf("no golden files under %s (run with -update to create them)", goldenDir)
	}
	for _, rel := range sortedKeys(want) {
		g, ok := got[rel]
		if !ok {
			t.Errorf("missing output file %s", rel)
			continue
		}
		if !bytes.Equal(g, want[rel]) {
			t.Errorf("%s differs from golden\n--- got ---\n%s\n--- want ---\n%s", rel, g, want[rel])
		}
	}
	for _, rel := range sortedKeys(got) {
		if _, ok := want[rel]; !ok {
			t.Errorf("unexpected output file %s", rel)
		}
	}
}

func TestE2EExitCodes(t *testing.T) {
	t.Run("help goes to stdout with exit 0", func(t *testing.T) {
		for _, arg := range []string{"-h", "-help", "--help"} {
			r := runBin(t, arg)
			if r.code != 0 || !strings.Contains(r.stdout, "使い方:") || r.stderr != "" {
				t.Errorf("%s: exit %d, stdout %d bytes, stderr %q", arg, r.code, len(r.stdout), r.stderr)
			}
		}
	})
	t.Run("no file is a usage error", func(t *testing.T) {
		r := runBin(t)
		if r.code != 2 || r.stdout != "" || !strings.Contains(r.stderr, "使い方:") {
			t.Errorf("exit %d, stdout %q, stderr %d bytes", r.code, r.stdout, len(r.stderr))
		}
	})
	t.Run("unknown flag is a usage error", func(t *testing.T) {
		if r := runBin(t, fixture, "-no-such-flag"); r.code != 2 {
			t.Errorf("exit %d, stderr:\n%s", r.code, r.stderr)
		}
	})
	t.Run("missing input fails with exit 1", func(t *testing.T) {
		r := runBin(t, filepath.Join(t.TempDir(), "nope.xlsx"), "-o", filepath.Join(t.TempDir(), "out"))
		if r.code != 1 || !strings.HasPrefix(r.stderr, "disassemble_excel: ") {
			t.Errorf("exit %d, stderr %q", r.code, r.stderr)
		}
	})
	t.Run("non-empty output dir needs -f", func(t *testing.T) {
		out := t.TempDir()
		if err := os.WriteFile(filepath.Join(out, "keep.txt"), []byte("x"), 0o644); err != nil {
			t.Fatal(err)
		}
		if r := runBin(t, fixture, "-o", out); r.code != 1 || !strings.Contains(r.stderr, "-f") {
			t.Errorf("without -f: exit %d, stderr %q", r.code, r.stderr)
		}
		if r := runBin(t, fixture, "-o", out, "-f"); r.code != 0 {
			t.Errorf("with -f: exit %d, stderr:\n%s", r.code, r.stderr)
		}
		if _, err := os.Stat(filepath.Join(out, "keep.txt")); err != nil {
			t.Errorf("-f must not delete existing files: %v", err)
		}
	})
}
